package io.mark.hditemicons;

import java.util.Objects;

/**
 * An override for an item's icon camera placement, named after the item definition fields it
 * stands in for. Angles are in Jau (0-2047 per turn), resize is out of 128.
 */
public final class CustomRotation {
	public final int xan2d;
	public final int yan2d;
	public final int zan2d;
	public final int zoom2d;
	public final int offsetX;
	public final int offsetY;
	public final int resizeX;
	public final int resizeY;
	public final int resizeZ;

	public CustomRotation(int xan2d, int yan2d, int zan2d, int zoom2d, int offsetX, int offsetY,
						int resizeX, int resizeY, int resizeZ) {
		this.xan2d = xan2d;
		this.yan2d = yan2d;
		this.zan2d = zan2d;
		this.zoom2d = zoom2d;
		this.offsetX = offsetX;
		this.offsetY = offsetY;
		this.resizeX = resizeX;
		this.resizeY = resizeY;
		this.resizeZ = resizeZ;
	}

	@Override
	public boolean equals(Object other) {
		if (this == other)
			return true;
		if (!(other instanceof CustomRotation))
			return false;
		CustomRotation that = (CustomRotation) other;
		return xan2d == that.xan2d && yan2d == that.yan2d && zan2d == that.zan2d && zoom2d == that.zoom2d
			&& offsetX == that.offsetX && offsetY == that.offsetY
			&& resizeX == that.resizeX && resizeY == that.resizeY && resizeZ == that.resizeZ;
	}

	@Override
	public int hashCode() {
		return Objects.hash(xan2d, yan2d, zan2d, zoom2d, offsetX, offsetY, resizeX, resizeY, resizeZ);
	}
}

package io.mark.hditemicons;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.BufferedReader;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Persists per-item {@link CustomRotation} overrides set from the rotation editor as JSON, so
 * they survive between sessions.
 */
@Slf4j
@Singleton
public class CustomRotationStorage {
	private static final String FILE_NAME = "custom-rotations.json";
	private static final String EDITOR_FILE_NAME = "icon-editor.json";
	private static final Type MAP_TYPE = new TypeToken<Map<Integer, CustomRotation>>() {}.getType();

	// A drag commits every 100ms and each commit rewrites the whole file, so writes wait for
	// the edits to settle.
	private static final long SAVE_DEBOUNCE_MS = 500;

	private final Gson gson;
	private final Map<Integer, CustomRotation> rotations = new ConcurrentHashMap<>();
	private final Map<String, Set<Integer>> groups = new ConcurrentHashMap<>();
	private final Map<String, CustomRotation> presets = new ConcurrentHashMap<>();

	@Nullable
	private Filepath directory;
	@Nullable
	private ScheduledExecutorService saveExecutor;
	@Nullable
	private ScheduledFuture<?> pendingSave;
	@Nullable
	private ScheduledFuture<?> pendingEditorSave;

	@Inject
	public CustomRotationStorage(Gson gson) {
		this.gson = gson;
	}

	public void load(Filepath directory) {
		this.directory = directory;
		saveExecutor = Executors.newSingleThreadScheduledExecutor(runnable -> {
			Thread thread = new Thread(runnable, "hd-item-icon-rotation-storage");
			thread.setDaemon(true);
			return thread;
		});

		Filepath file = directory.join(FILE_NAME);
		if (file.isFile()) {
			try (BufferedReader reader = file.openBufferedReader()) {
				Map<Integer, CustomRotation> loaded = gson.fromJson(reader, MAP_TYPE);
				if (loaded != null)
					rotations.putAll(loaded);
			} catch (IOException | JsonSyntaxException e) {
				log.debug("Couldn't read custom icon rotations from {}, starting empty", file, e);
			}
		}

		Filepath editorFile = directory.join(EDITOR_FILE_NAME);
		if (!editorFile.isFile())
			return;
		try (BufferedReader reader = editorFile.openBufferedReader()) {
			take(gson.fromJson(reader, IconEditorData.class));
		} catch (IOException | JsonSyntaxException e) {
			log.debug("Couldn't read icon groups and presets from {}, starting empty", editorFile, e);
		}
	}

	public synchronized void reset() {
		ScheduledExecutorService executor = saveExecutor;
		Filepath currentDirectory = directory;

		boolean saveWasPending = pendingSave != null && pendingSave.cancel(false);
		boolean editorSaveWasPending = pendingEditorSave != null && pendingEditorSave.cancel(false);
		pendingSave = null;
		pendingEditorSave = null;
		if (executor != null) {
			// Snapshot before the clear below, or the flush writes an empty file
			if (saveWasPending && currentDirectory != null) {
				Map<Integer, CustomRotation> snapshot = Map.copyOf(rotations);
				executor.execute(() -> writeToDisk(currentDirectory, snapshot));
			}
			if (editorSaveWasPending && currentDirectory != null) {
				IconEditorData snapshot = editorData();
				executor.execute(() -> writeEditorDataToDisk(currentDirectory, snapshot));
			}
			// shutdown(), not shutdownNow(), so that last write still runs - neither blocks
			executor.shutdown();
		}

		saveExecutor = null;
		directory = null;
		rotations.clear();
		groups.clear();
		presets.clear();
	}

	@Nullable
	public CustomRotation get(int itemId) {
		return rotations.get(itemId);
	}

	public Map<Integer, CustomRotation> all() {
		return Map.copyOf(rotations);
	}

	public void put(int itemId, CustomRotation rotation) {
		rotations.put(itemId, rotation);
		persist();
	}

	public void remove(int itemId) {
		rotations.remove(itemId);
		persist();
	}

	public void putAll(Iterable<Integer> itemIds, @Nullable CustomRotation rotation) {
		for (int itemId : itemIds) {
			if (rotation == null)
				rotations.remove(itemId);
			else
				rotations.put(itemId, rotation);
		}
		persist();
	}

	public List<String> groupNames() {
		List<String> names = new ArrayList<>(groups.keySet());
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return names;
	}

	public Set<Integer> groupMembers(int itemId) {
		String name = groupOf(itemId);
		return name == null ? Set.of(itemId) : membersOf(name);
	}

	public Set<Integer> membersOf(String groupName) {
		Set<Integer> members = groups.get(groupName);
		return members == null ? Set.of() : snapshot(members);
	}

	@Nullable
	public String groupOf(int itemId) {
		for (Map.Entry<String, Set<Integer>> group : groups.entrySet())
			if (group.getValue().contains(itemId))
				return group.getKey();
		return null;
	}

	public void createGroup(String name) {
		groups.computeIfAbsent(name, key -> newMemberSet());
		persistEditorData();
	}

	public void renameGroup(String from, String to) {
		Set<Integer> members = groups.remove(from);
		if (members == null)
			return;
		groups.put(to, members);
		persistEditorData();
	}

	public String unusedGroupName(String prefix) {
		for (int suffix = 1; ; suffix++) {
			String name = prefix + " " + suffix;
			if (!groups.containsKey(name))
				return name;
		}
	}

	public void deleteGroup(String name) {
		groups.remove(name);
		persistEditorData();
	}

	public void addToGroup(String name, int itemId) {
		for (Set<Integer> members : groups.values())
			members.remove(itemId);
		groups.computeIfAbsent(name, key -> newMemberSet()).add(itemId);
		persistEditorData();
	}

	public void leaveGroup(int itemId) {
		for (Set<Integer> members : groups.values())
			members.remove(itemId);
		persistEditorData();
	}

	public List<String> presetNames() {
		List<String> names = new ArrayList<>(presets.keySet());
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return names;
	}

	@Nullable
	public CustomRotation preset(String name) {
		return presets.get(name);
	}

	public void putPreset(String name, CustomRotation rotation) {
		presets.put(name, rotation);
		persistEditorData();
	}

	public void removePreset(String name) {
		presets.remove(name);
		persistEditorData();
	}

	public String exportToJson() {
		return gson.toJson(new IconEditorData(Map.copyOf(rotations), copyOfGroups(), Map.copyOf(presets)));
	}

	@Nullable
	public ImportPreview readImport(String json) {
		IconEditorData data;
		try {
			data = gson.fromJson(json, IconEditorData.class);
		} catch (JsonSyntaxException e) {
			log.debug("Couldn't read an icon editor export", e);
			return null;
		}
		if (data == null)
			return null;

		clean(data);
		ImportPreview preview = new ImportPreview(data);
		if (data.rotations != null)
			for (Integer itemId : data.rotations.keySet())
				if (rotations.containsKey(itemId))
					preview.rotationsReplaced.add(itemId);
		if (data.groups != null)
			for (String name : data.groups.keySet())
				if (groups.containsKey(name))
					preview.groupsReplaced.add(name);
		if (data.presets != null)
			for (String name : data.presets.keySet())
				if (presets.containsKey(name))
					preview.presetsReplaced.add(name);
		return preview;
	}

	public ImportCounts applyImport(IconEditorData chosen) {
		ImportCounts counts = take(chosen);
		if (counts.rotations > 0)
			persist();
		if (counts.groups > 0 || counts.presets > 0)
			persistEditorData();
		return counts;
	}

	private ImportCounts take(@Nullable IconEditorData data) {
		ImportCounts counts = new ImportCounts();
		if (data == null)
			return counts;

		clean(data);
		if (data.rotations != null) {
			rotations.putAll(data.rotations);
			counts.rotations = data.rotations.size();
		}
		if (data.groups != null) {
			for (Map.Entry<String, Set<Integer>> group : data.groups.entrySet()) {
				Set<Integer> members = newMemberSet();
				members.addAll(group.getValue());
				groups.put(group.getKey(), members);
				counts.groups++;
			}
		}
		if (data.presets != null) {
			presets.putAll(data.presets);
			counts.presets = data.presets.size();
		}
		return counts;
	}

	private static void clean(IconEditorData data) {
		if (data.rotations != null)
			data.rotations.values().removeIf(Objects::isNull);
		if (data.groups != null)
			data.groups.values().removeIf(Objects::isNull);
		if (data.presets != null)
			data.presets.values().removeIf(Objects::isNull);
	}

	public static final class ImportCounts {
		public int rotations;
		public int groups;
		public int presets;
	}

	public static final class ImportPreview {
		public final IconEditorData data;
		public final Set<Integer> rotationsReplaced = new HashSet<>();
		public final Set<String> groupsReplaced = new HashSet<>();
		public final Set<String> presetsReplaced = new HashSet<>();

		ImportPreview(IconEditorData data) {
			this.data = data;
		}

		public boolean isEmpty() {
			return count(data.rotations) == 0 && count(data.groups) == 0 && count(data.presets) == 0;
		}

		private static int count(@Nullable Map<?, ?> map) {
			return map == null ? 0 : map.size();
		}
	}

	public void offDisk(Runnable task) {
		ScheduledExecutorService executor = saveExecutor;
		if (executor != null)
			executor.execute(task);
	}

	private static Set<Integer> newMemberSet() {
		return Collections.synchronizedSet(new LinkedHashSet<>());
	}

	private static Set<Integer> snapshot(Set<Integer> members) {
		synchronized (members) {
			return Set.copyOf(members);
		}
	}

	private Map<String, Set<Integer>> copyOfGroups() {
		Map<String, Set<Integer>> copy = new TreeMap<>(Comparator.nullsFirst(String.CASE_INSENSITIVE_ORDER));
		for (Map.Entry<String, Set<Integer>> group : groups.entrySet())
			copy.put(group.getKey(), snapshot(group.getValue()));
		return copy;
	}

	private IconEditorData editorData() {
		return new IconEditorData(null, copyOfGroups(), Map.copyOf(presets));
	}

	private synchronized void persist() {
		Filepath currentDirectory = directory;
		ScheduledExecutorService executor = saveExecutor;
		if (currentDirectory == null || executor == null)
			return;

		if (pendingSave != null)
			pendingSave.cancel(false);
		// Snapshotted when the write runs, so it carries the settled values, not the first of the burst
		pendingSave = executor.schedule(() -> writeToDisk(currentDirectory, Map.copyOf(rotations)),
			SAVE_DEBOUNCE_MS, TimeUnit.MILLISECONDS);
	}

	private synchronized void persistEditorData() {
		Filepath currentDirectory = directory;
		ScheduledExecutorService executor = saveExecutor;
		if (currentDirectory == null || executor == null)
			return;

		if (pendingEditorSave != null)
			pendingEditorSave.cancel(false);
		pendingEditorSave = executor.schedule(() -> writeEditorDataToDisk(currentDirectory, editorData()),
			SAVE_DEBOUNCE_MS, TimeUnit.MILLISECONDS);
	}

	private void writeToDisk(Filepath currentDirectory, Map<Integer, CustomRotation> snapshot) {
		try {
			if (!currentDirectory.isDirectory())
				currentDirectory.createDirectories();
			currentDirectory.join(FILE_NAME).write(gson.toJson(snapshot, MAP_TYPE));
		} catch (IOException e) {
			log.debug("Couldn't save custom icon rotations to {}", currentDirectory, e);
		}
	}

	private void writeEditorDataToDisk(Filepath currentDirectory, IconEditorData snapshot) {
		try {
			if (!currentDirectory.isDirectory())
				currentDirectory.createDirectories();
			currentDirectory.join(EDITOR_FILE_NAME).write(gson.toJson(snapshot));
		} catch (IOException e) {
			log.debug("Couldn't save icon groups and presets to {}", currentDirectory, e);
		}
	}
}

package io.mark.hditemicons;

import javax.inject.Inject;
import net.runelite.client.util.HotkeyListener;

/** Tracks whether the hotkey is held, since the menu entry has no key event to match against. */
class EditRotationHotkeyListener extends HotkeyListener {
	private volatile boolean pressed;

	@Inject
	EditRotationHotkeyListener(HdItemIconsConfig config) {
		super(config::editRotationHotkey);
	}

	@Override
	public void hotkeyPressed() {
		pressed = true;
	}

	@Override
	public void hotkeyReleased() {
		pressed = false;
	}

	boolean isPressed() {
		return pressed;
	}
}

package io.mark.hditemicons;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(HdItemIconsConfig.GROUP)
public interface HdItemIconsConfig extends Config {

	String GROUP = "hd-item-icons";

	@ConfigItem(
		keyName = "iconCacheStorage",
		name = "Icon cache storage",
		description = "Memory only keeps rendered icons for the current session. Disk also saves them"
			+ " to your plugin data folder so they don't need to be re-rendered next time you log in.",
		position = 0
	)
	default IconCacheStorage iconCacheStorage() {
		return IconCacheStorage.MEMORY;
	}

	@ConfigItem(
		keyName = "iconQuality",
		name = "Icon quality",
		description = "Controls how much antialiasing supersampling is used when rendering icons."
			+ " Higher quality looks smoother but takes longer to render each icon. No antialiasing"
			+ " renders fastest, with hard edges and thin parts of a model likely to be left out.",
		position = 1
	)
	default IconQuality iconQuality() {
		return IconQuality.NONE;
	}

	@ConfigItem(
		keyName = "animateTextures",
		name = "Animate textures",
		description = "Scrolls the animated textures on an item's model the way the game scrolls them on"
			+ " objects in the world, so icons of items made of water, lava and the like move. Every frame"
			+ " of an item's animation is rendered once and then cached, so it only costs the once.",
		position = 2
	)
	default boolean animateTextures() {
		return true;
	}

	@Range(min = 1, max = 8)
	@ConfigItem(
		keyName = "renderThreadCount",
		name = "Render threads",
		description = "How many background threads render icons at once. Higher can render icons faster"
			+ " when many are queued at once (e.g. opening a full bank), at the cost of more CPU usage.",
		position = 3
	)
	default int renderThreadCount() {
		return 2;
	}

	@ConfigItem(
		keyName = "customRotationsEnabled",
		name = "Custom icon rotations",
		description = "Turn off to render every item's default icon rotation and ignore any custom rotations"
			+ " you've saved. Saved rotations aren't deleted, so re-enabling restores them.",
		position = 4
	)
	default boolean customRotationsEnabled() {
		return true;
	}

	@ConfigItem(
		keyName = "editRotationHotkey",
		name = "Edit icon rotation hotkey",
		description = "Hold this while right-clicking an item to add an \"Edit icon rotation\" option to its menu.",
		position = 5
	)
	default Keybind editRotationHotkey() {
		return Keybind.SHIFT;
	}

	@ConfigItem(
		keyName = "sidePanelEditor",
		name = "Edit icons in the side panel",
		description = "Adds an HQ Item Icons button to the side panel and edits icons there instead of in a"
			+ " pop-up window. Picking \"Edit icon rotation\" on an item opens the panel on that item.",
		position = 6
	)
	default boolean sidePanelEditor() {
		return true;
	}
}

package io.mark.hditemicons;

import com.google.inject.Provides;
import io.mark.hditemicons.hd.HdItemIcons;
import io.mark.hditemicons.hd.IconEditorSidePanel;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "HQ Item Icons",
	description = "Sharper, high quality item icons",
	tags = {"hq", "hd", "item", "icons", "inventory", "bank", "antialiasing"},
	internalName = "hq-item-icons"
)
public class HdItemIconsPlugin extends Plugin {

	private static final String NAMESPACE = "hq-item-icons";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private HdItemIcons hdItemIcons;

	@Inject
	private KeyManager keyManager;

	@Inject
	private EditRotationHotkeyListener editRotationHotkeyListener;

	@Inject
	private HdItemIconsConfig config;

	@Inject
	private IconEditorSidePanel sidePanel;

	@Provides
	HdItemIconsConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(HdItemIconsConfig.class);
	}

	@Override
	protected void startUp() throws IOException {
		hdItemIcons.startUp(getPluginDirectory());
		keyManager.registerKeyListener(editRotationHotkeyListener);
		if (config.sidePanelEditor())
			sidePanel.attach();
		eventBus.post(new PluginMessage(NAMESPACE, "startup", Map.of("plugin", getName())));
	}

	@Override
	protected void shutDown() {
		keyManager.unregisterKeyListener(editRotationHotkeyListener);
		sidePanel.detach();
		hdItemIcons.shutDown();
		eventBus.post(new PluginMessage(NAMESPACE, "shutdown", Map.of("plugin", getName())));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!HdItemIconsConfig.GROUP.equals(event.getGroup()) || !"sidePanelEditor".equals(event.getKey()))
			return;

		if (config.sidePanelEditor())
			sidePanel.attach();
		else
			sidePanel.detach();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage event) {
		if (!NAMESPACE.equals(event.getNamespace()))
			return;

		Object value;
		if ("update-icon".equals(event.getName()))
			value = event.getData().get("itemId");
		else if ("update-icons".equals(event.getName()))
			value = event.getData().get("itemIds");
		else
			return;

		// No ids at all means every icon; an empty or malformed one means none, so that a bad
		// message can't wipe the whole cache by accident
		if (value == null) {
			clientThread.invoke(() -> hdItemIcons.clearRenderCache());
			return;
		}

		List<Integer> itemIds = itemIdsOf(value);
		clientThread.invoke(() -> hdItemIcons.clearRenderCache(itemIds));
	}

	/** Another plugin owns what it sent, so this copies eagerly and ignores anything unusable. */
	private static List<Integer> itemIdsOf(Object value) {
		if (value instanceof Number)
			return List.of(((Number) value).intValue());
		if (!(value instanceof Collection))
			return List.of();

		List<Integer> itemIds = new ArrayList<>();
		for (Object element : (Collection<?>) value)
			if (element instanceof Number)
				itemIds.add(((Number) element).intValue());
		return itemIds;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		int itemId = event.getItemId();
		if (itemId == -1
			|| event.getMenuEntry().getWidget() == null
			|| !"Examine".equals(event.getOption())
			|| !editRotationHotkeyListener.isPressed()
			|| !config.customRotationsEnabled())
			return;

		client.getMenu().createMenuEntry(-1)
			.setOption("Edit icon rotation")
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> hdItemIcons.openRotationEditor(itemId));
	}
}

package io.mark.hditemicons;

public enum IconCacheStorage {
	MEMORY("Memory only"),
	DISK("Disk");

	private final String label;

	IconCacheStorage(String label) {
		this.label = label;
	}

	@Override
	public String toString() {
		return label;
	}
}

package io.mark.hditemicons;

import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;

public final class IconEditorData {
	@Nullable
	public Map<Integer, CustomRotation> rotations;
	@Nullable
	public Map<String, Set<Integer>> groups;
	@Nullable
	public Map<String, CustomRotation> presets;

	public IconEditorData() {
	}

	public IconEditorData(@Nullable Map<Integer, CustomRotation> rotations,
						@Nullable Map<String, Set<Integer>> groups,
						@Nullable Map<String, CustomRotation> presets) {
		this.rotations = rotations;
		this.groups = groups;
		this.presets = presets;
	}
}

package io.mark.hditemicons;

import java.util.Collection;
import java.util.List;
import java.util.function.Consumer;

public interface IconEditorHost {
	void iconsChanged(Collection<Integer> itemIds);

	void allIconsChanged();

	void findSimilarItems(int itemId, Consumer<SimilarItems> onFound);

	void itemIndex(Consumer<List<NamedItem>> onReady);

	void editItem(int itemId);
}

package io.mark.hditemicons;

import lombok.Getter;

public enum IconQuality {
	NONE(1, "No antialiasing"),
	LOW(2, "Low"),
	MEDIUM(4, "Medium"),
	HIGH(6, "High");

	@Getter
    private final int supersample;
	private final String label;

	IconQuality(int supersample, String label) {
		this.supersample = supersample;
		this.label = label;
	}

    @Override
	public String toString() {
		return label;
	}
}

package io.mark.hditemicons;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The bundled item_render_sheet.csv (see tools/item-render-sheet-generator). RuneLite's API
 * exposes an item's rotation angles but none of these fields, so they come from the cache dump.
 */
@Slf4j
@Singleton
public class ItemRenderSheet {
	public static final int DEFAULT_ZOOM_2D = 2000;
	public static final int DEFAULT_RESIZE = 128;

	public static final class Placement {
		public final int zoom2d;
		public final int offsetX;
		public final int offsetY;
		public final int resizeX;
		public final int resizeY;
		public final int resizeZ;

		Placement(int zoom2d, int offsetX, int offsetY, int resizeX, int resizeY, int resizeZ) {
			this.zoom2d = zoom2d;
			this.offsetX = offsetX;
			this.offsetY = offsetY;
			this.resizeX = resizeX;
			this.resizeY = resizeY;
			this.resizeZ = resizeZ;
		}
	}

	private static final Placement DEFAULT_PLACEMENT =
		new Placement(DEFAULT_ZOOM_2D, 0, 0, DEFAULT_RESIZE, DEFAULT_RESIZE, DEFAULT_RESIZE);

	private final Map<Integer, Placement> placements = load();

	public Placement get(int itemId) {
		return placements.getOrDefault(itemId, DEFAULT_PLACEMENT);
	}

	private static Map<Integer, Placement> load() {
		Map<Integer, Placement> result = new HashMap<>();
		try (InputStream in = ItemRenderSheet.class.getResourceAsStream("item_render_sheet.csv")) {
			if (in == null) {
				log.warn("item_render_sheet.csv is missing from resources");
				return result;
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null) {
				if (line.isEmpty() || line.charAt(0) == '#' || line.startsWith("id,"))
					continue;
				String[] parts = line.split(",", -1);
				int itemId = Integer.parseInt(parts[0]);
				result.put(itemId, new Placement(
					parseOr(parts[1], DEFAULT_ZOOM_2D),
					parseOr(parts[2], 0),
					parseOr(parts[3], 0),
					parseOr(parts[4], DEFAULT_RESIZE),
					parseOr(parts[5], DEFAULT_RESIZE),
					parseOr(parts[6], DEFAULT_RESIZE)));
			}
		} catch (IOException e) {
			log.warn("Couldn't read item_render_sheet.csv", e);
		}
		return result;
	}

	private static int parseOr(String value, int defaultValue) {
		return value.isEmpty() ? defaultValue : Integer.parseInt(value);
	}
}

package io.mark.hditemicons;

import java.util.Locale;

public final class NamedItem {
	public final int id;
	public final String name;
	private final String searchName;

	public NamedItem(int id, String name) {
		this.id = id;
		this.name = name;
		this.searchName = name.toLowerCase(Locale.ROOT);
	}

	public boolean nameContains(String lowerCaseQuery) {
		return searchName.contains(lowerCaseQuery);
	}

	public boolean nameStartsWith(String lowerCaseQuery) {
		return searchName.startsWith(lowerCaseQuery);
	}

	@Override
	public String toString() {
		return name + " (" + id + ")";
	}
}

